import{_ as t,c as s,o as r,ag as a}from"./chunks/framework.Cycwnjj0.js";const n="/assets/comparison-table-shortcode.Z0Rl6D5O.webp",o="/assets/paste-shortcode-in-a-page.DC8AUaSo.webp",d="/assets/preview-of-comparison-table.BsKQyg-r.webp",i="/assets/product-table-shortcode.BsgSpsKR.webp",p="/assets/preview-of-product-table.DpVpm_3L.webp",m="/assets/custom-product-tables-shortcode.C3_ow7_-.webp",c="/assets/preview-of-custom-products.Bo1gi7xA.webp",f=JSON.parse('{"title":"Embed Amazon/Custom Product Tables into Posts/Pages","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/embed-amazon-custom-product-tables-into-posts-pages.md","filePath":"guide/getting-started/embed-amazon-custom-product-tables-into-posts-pages.md"}'),l={name:"guide/getting-started/embed-amazon-custom-product-tables-into-posts-pages.md"};function b(u,e,h,g,P,w){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="embed-amazon-custom-product-tables-into-posts-pages" tabindex="-1">Embed Amazon/Custom Product Tables into Posts/Pages <a class="header-anchor" href="#embed-amazon-custom-product-tables-into-posts-pages" aria-label="Permalink to &quot;Embed Amazon/Custom Product Tables into Posts/Pages&quot;">​</a></h1><p>AzonPress allows you to embed your <strong>Amazon Product</strong> tables, <strong>Amazon Comparison</strong> tables, and <strong>Custom Product</strong> tables easily to the front end (i.e., Posts or Pages) on your WordPress Site using the <strong>Shortcode</strong>. This article will guide you through embedding these tables from AzonPress to your desired Posts/Pages.</p><h2 id="how-to-embed-product-tables-from-azonpress" tabindex="-1">How To Embed Product Tables From AzonPress <a class="header-anchor" href="#how-to-embed-product-tables-from-azonpress" aria-label="Permalink to &quot;How To Embed Product Tables From AzonPress&quot;">​</a></h2><p>In AzonPress, you have major Three types of product tables. These are:</p><ul><li>Amazon Comparison Tables</li><li>Amazon Products Tables</li><li>Custom Product Tables (Single &amp; Multiple)</li></ul><p>To learn how you can embed these above-mentioned tables to your desired Posts/Pages, follow the steps with the screenshots below –</p><h3 id="embed-amazon-comparison-table" tabindex="-1">Embed Amazon Comparison Table <a class="header-anchor" href="#embed-amazon-comparison-table" aria-label="Permalink to &quot;Embed Amazon Comparison Table&quot;">​</a></h3><p>First, go to the <strong>Amazon Comparisons</strong> from the left sidebar or <strong>Comparison Tables</strong> from the <strong>Amazon</strong> dropdown placed in the top right corner inside the <strong>AzonPress Dashboard</strong>.</p><p><strong>Remember</strong>, you need to connect your AzonPress with your Amazon Associate Account to get this Amazon dropdown option in the AzonPress Navbar.</p><p>Now, copy the <strong>Shortcode</strong> of your desired table by clicking the box.</p><p><img src="'+n+'" alt="Comparison Tables shortcode"></p><p>Then, paste the shortcode to your desired Post/Page where you want to display this table and press the <strong>Publish</strong> button.</p><p><img src="'+o+'" alt="Paste shortcode in a page"></p><p>Here is a preview of how your table will exactly look in the front end.</p><p><img src="'+d+'" alt="Preview of Comparison table"></p><h3 id="embed-amazon-product-table" tabindex="-1">Embed Amazon Product Table <a class="header-anchor" href="#embed-amazon-product-table" aria-label="Permalink to &quot;Embed Amazon Product Table&quot;">​</a></h3><p>First, go to the <strong>Amazon Products</strong> from the left sidebar or <strong>Comparison Tables</strong> from the <strong>Amazon</strong> dropdown placed in the top right corner inside the <strong>AzonPress Dashboard</strong>.</p><p><strong>Remember</strong>, you need to connect your AzonPress with your Amazon Associate Account to get this Amazon dropdown option in the AzonPress Navbar.</p><p>Now, copy the <strong>Shortcode</strong> of your desired table by clicking the box.</p><p><img src="'+i+'" alt="Product Tables Shortcode"></p><p>Then, paste the shortcode to your desired Post/Page where you want to display this table and press the <strong>Publish</strong> button.</p><p><img src="'+o+'" alt="Paste shortcode in a page"></p><p>Here is a preview of how your table will exactly look in the front end.</p><p><img src="'+p+'" alt="Preview of Product table"></p><h3 id="embed-custom-products-tables" tabindex="-1">Embed Custom Products Tables <a class="header-anchor" href="#embed-custom-products-tables" aria-label="Permalink to &quot;Embed Custom Products Tables&quot;">​</a></h3><p>First, go to <strong>Custom Products</strong> from the <strong>WordPress</strong> sidebar or <strong>AzonPress</strong> Navbar.</p><p><strong>Remember</strong>, with the Custom Products feature, besides Amazon, you can fetch data from other E-Commerce websites such as eBay and Etsy.</p><p>Now, copy the <strong>Shortcode</strong> of your desired table by clicking the box.</p><p><img src="'+m+'" alt="Custom Product Tables Shortcode"></p><p>Then, paste the shortcode to your desired Post/Page where you want to display this table and press the <strong>Publish</strong> button.</p><p><img src="'+o+'" alt="Paste shortcode in a page"></p><p>Here is a preview of how your table will exactly look in the front end.</p><p><img src="'+c+'" alt="Preview of Custom Products"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',35)])])}const z=t(l,[["render",b]]);export{f as __pageData,z as default};
